## Step 4. Write the Gherkin first: `features/pi_worker.feature`

```gherkin
Feature: A bot's Pi session carries its conversation across turns
  As a household member
  I want a bot answered by the Pi worker to remember what was already said
  So that each turn sends the model only what is new while the session holds the rest

  The Pi worker keeps one durable session per tenant, bot and channel. The
  session history carries earlier turns. The first time a session meets a
  channel it is given the whole transcript, including the bot's own earlier
  lines; after that it is given only the lines it has not yet seen.

  Background:
    Given an empty control plane
    And tenant "anthus" user "ryan" has a channel with a named bot "Ping"

  Scenario: The second turn's model input includes the first exchange
    When user "ryan" of tenant "anthus" posts "My favorite number is forty-two." addressed to bot "Ping" on the channel
    And bot "Ping" answers the next turn on the Pi worker with "Noted."
    And user "ryan" of tenant "anthus" posts "What is my favorite number?" addressed to bot "Ping" on the channel
    And bot "Ping" answers the next turn on the Pi worker with "Forty-two."
    Then the Pi worker model input includes "My favorite number is forty-two."
    And the Pi worker model input includes "Noted."
    And the Pi worker model input includes "What is my favorite number?"

  Scenario: A new Pi session is given the bot's own earlier lines
    When user "ryan" of tenant "anthus" posts "hello" addressed to bot "Ping" on the channel
    And bot "Ping" runs one computerless worker turn
    And user "ryan" of tenant "anthus" posts "what did you just say?" addressed to bot "Ping" on the channel
    And bot "Ping" answers the next turn on the Pi worker with "I said hello back."
    Then the Pi worker model input includes the bot's earlier answer
    And the Pi worker model input includes "what did you just say?"
```

## Step 5. `features/steps/pi_worker_helpers.py` (a helper module with no step decorators)

```python
"""Shared helpers that run the TypeScript Pi worker through its tsx harness."""

from __future__ import annotations

import json
import shutil
import subprocess
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
HARNESS = ROOT / "conversation" / "test-support" / "pi-worker-harness.ts"


def pi_storage_directory(context: object) -> str:
    """Return the per-scenario directory that persists Pi sessions across runs."""
    directory = getattr(context, "pi_storage_dir", None)
    if directory is None:
        directory = tempfile.mkdtemp(prefix="pi-sessions-")
        context.pi_storage_dir = directory
        context.add_cleanup(shutil.rmtree, directory, True)
    return directory


def run_pi_worker_for_bot(
    context: object, bot_id: str, script: list[dict[str, str]]
) -> dict[str, object]:
    """Run the oldest queued job of ``bot_id`` through the Pi worker.

    A handler that returns normally acknowledges its SQS message, so the job
    leaves the in-memory queue whatever the outcome.
    """
    channel = context.last_channel
    jobs = list(context.plane.pending_jobs_for_bot(bot_id))
    assert jobs, f"no queued job for bot {bot_id}"
    job = jobs[0]
    payload = {
        "baseUrl": str(context.api_client.base_url),
        "tenantId": channel.tenant_id,
        "job": {
            "job_id": job.job_id,
            "tenant_id": job.tenant_id,
            "turn_id": job.turn_id,
            "bot_id": job.bot_id,
            "required_capabilities": sorted(job.required_capabilities),
        },
        "script": script,
        "storageDir": pi_storage_directory(context),
    }
    completed = subprocess.run(
        ["npx", "tsx", str(HARNESS), json.dumps(payload)],
        cwd=ROOT,
        check=True,
        capture_output=True,
        text=True,
    )
    result = json.loads(completed.stdout.strip().splitlines()[-1])
    context.plane.remove_pending_job(job.job_id)
    context.pi_worker_result = result
    return result
```

## Step 6. `features/steps/pi_worker_steps.py`

```python
"""Behavior steps for the Pi worker's session history."""

from __future__ import annotations

from behave import then, when
from pi_worker_helpers import run_pi_worker_for_bot


@when('bot "{name}" answers the next turn on the Pi worker with "{text}"')
def when_bot_answers_on_pi_worker(context: object, name: str, text: str) -> None:
    bot = context.bots_by_name[name]
    result = run_pi_worker_for_bot(context, bot.bot_id, [{"text": text}])
    assert result["outcome"] == "answered", result


@then('the Pi worker model input includes "{text}"')
def then_pi_input_includes(context: object, text: str) -> None:
    request = context.pi_worker_result["lastRequestText"]
    assert text in request, request


@then("the Pi worker model input includes the bot's earlier answer")
def then_pi_input_includes_earlier_answer(context: object) -> None:
    channel = context.last_channel
    messages = context.plane.list_channel_messages(
        channel.channel_id, channel.tenant_id, 0
    )
    earlier = next(m for m in messages if m.author_kind == "bot")
    request = context.pi_worker_result["lastRequestText"]
    assert earlier.body in request, request
```

Run `cd python && behave ../features/pi_worker.feature`. It must FAIL because `conversation/test-support/pi-worker-harness.ts` does not exist yet (the subprocess fails). If it fails for another reason, such as an undefined step, STOP and report.

## Step 7. `conversation/src/turn-runner.ts`

```ts
import type { Context } from "@earendil-works/chord";
import { withoutAbortSignal } from "@earendil-works/chord/context";
import type { Models } from "@earendil-works/pi-ai/models";
import {
	AssistantEntry,
	createRegistry,
	defineDoc,
	defineExtension,
	Harness,
	section,
} from "@earendil-works/pi-durable";
import type { Storage } from "@earendil-works/pi-durable";

export type ChannelLine = {
	seq: number;
	authorKind: "human" | "bot";
	authorId: string;
	authorLabel: string;
	body: string;
};

export type TurnInput = {
	turnId: string;
	botId: string;
	botName: string;
	memory: Record<string, string>;
	lines: ChannelLine[];
	promptMessageSeq: number;
};

export type TurnModel = { provider: string; modelId: string; thinkingLevel: "off" | "minimal" | "low" };

export type TurnOutcome =
	| { kind: "answered"; text: string; usage: { input: number; output: number } }
	| { kind: "failed"; reason: string };

export const ChannelSyncDoc = defineDoc({
	kind: "chatticus.channel-sync",
	version: 1,
	scope: "conversation",
	history: "latest",
	fork: "current",
	initial: () => ({ lastSyncedSeq: 0 }),
});

export function buildSystemPrompt(input: Pick<TurnInput, "botName" | "memory">): string {
	const memoryLines = Object.keys(input.memory)
		.sort()
		.map((key) => `memory ${key}: ${input.memory[key]}`);
	return [`You are ${input.botName}, a teammate in a Chatticus conversation. Answer briefly.`, ...memoryLines].join("
");
}

export function selectLinesToSync(input: TurnInput, lastSyncedSeq: number): ChannelLine[] {
	return input.lines.filter(
		(line) =>
			line.seq > lastSyncedSeq &&
			line.seq <= input.promptMessageSeq &&
			(lastSyncedSeq === 0 || !(line.authorKind === "bot" && line.authorId === input.botId)),
	);
}

export function formatLines(lines: ChannelLine[]): string {
	return lines.map((line) => `${line.authorLabel}: ${line.body}`).join("
");
}

export function classifyError(errorMessage: string | undefined): { reason: string } {
	const message = errorMessage ?? "";
	if (message.includes("insufficient_quota")) {
		return { reason: "The model provider refused the request: the account is out of credits or over its quota." };
	}
	if (message.includes("401") || message.includes("invalid_api_key")) {
		return { reason: "The model provider rejected the API key." };
	}
	if (message.includes("model_access_denied")) {
		return { reason: "The model provider denied access to the configured model." };
	}
	if (message.includes("unsupported_value") || message.includes("invalid_request_error")) {
		return { reason: "The model provider rejected the request as invalid." };
	}
	return { reason: "The model provider failed to produce an answer." };
}

export async function runTurn(
	storage: Storage,
	models: Models,
	model: TurnModel,
	input: TurnInput,
	context: Context,
	options?: { retryBaseDelayMs?: number },
): Promise<TurnOutcome> {
	const registry = createRegistry();
	registry.install(
		defineExtension({
			name: "chatticus",
			sections: [section("chatticus-system", () => buildSystemPrompt(input), { tag: false })],
		}),
	);
	const harness = await Harness.open(storage, { models, registry, settings: { retry: { maxRetries: 2, ...(options?.retryBaseDelayMs === undefined ? {} : { baseDelayMs: options.retryBaseDelayMs }) } } }, context);
	try {
		const agent = { model: { provider: model.provider, modelId: model.modelId }, thinkingLevel: model.thinkingLevel };
		const root = await harness.root(context, { agent });
		await root.configure(agent, context);
		const synced = await harness.snapshot(ChannelSyncDoc, root.id, context);
		const lastSyncedSeq = synced?.lastSyncedSeq ?? 0;
		const content = formatLines(selectLinesToSync(input, lastSyncedSeq));
		const requestId = `turn:${input.turnId}`;
		const existing = await root.commit((tx) => tx.submissionByRequest(root.id, requestId), context);
		if (existing === undefined && content.trim() === "") {
			return { kind: "failed", reason: "There was nothing new to answer." };
		}
		const submission = await root.submit({ type: "input", content, requestId }, context);
		const settled = await submission.wait(context);
		if (settled.type !== "input") return { kind: "failed", reason: "The turn was not an input." };
		if (settled.entry !== undefined) {
			await root.commit(async (tx) => {
				const doc = await tx.doc(ChannelSyncDoc, root.id);
				doc.lastSyncedSeq = input.promptMessageSeq;
			}, context);
		}
		if (settled.status === "unanswered") {
			if (settled.reason === "model_error") return { kind: "failed", ...classifyError(typeof settled.detail === "string" ? settled.detail : JSON.stringify(settled.detail)) };
			return { kind: "failed", reason: `The turn was not answered (${settled.reason}).` };
		}
		const entry = await root.commit((tx) => tx.entry(AssistantEntry, settled.answer as never), context);
		const message = entry?.model?.[0];
		if (message?.role !== "assistant") return { kind: "failed", reason: "The turn produced no assistant message." };
		const text = message.content.map((part) => (part.type === "text" ? part.text : "")).join("");
		return { kind: "answered", text, usage: { input: message.usage.input, output: message.usage.output } };
	} finally {
		await harness.close(withoutAbortSignal(context));
	}
}
```

## Step 8. `conversation/src/front-door-client.ts`

```ts
export type FrontDoorClientOptions = {
	baseUrl: string;
	tenantId: string;
	invokeKey?: string;
};

export type ClaimResult = { acquired: boolean; fenceToken: number } | { acquired: false };

export type TurnContextMessage = {
	message_id: string;
	channel_id: string;
	tenant_id: string;
	seq: number;
	author_kind: "human" | "bot";
	author_id: string;
	body: string;
	addressed_to_bot_id: string | null;
	created_at: string | null;
};

export type TurnContext = {
	turn_id: string;
	channel_id: string;
	bot_id: string;
	bot_name: string;
	memory: Record<string, string>;
	prompt_message_seq: number;
	messages: TurnContextMessage[];
};

export class FrontDoorError extends Error {
	readonly status: number;
	readonly body: string;

	constructor(status: number, body: string) {
		super(`front door answered ${status}: ${body.slice(0, 300)}`);
		this.name = "FrontDoorError";
		this.status = status;
		this.body = body;
	}
}

export class FrontDoorClient {
	private readonly baseUrl: string;
	private readonly tenantId: string;
	private readonly invokeKey: string | undefined;
	private token: string | undefined;

	constructor(options: FrontDoorClientOptions) {
		this.baseUrl = options.baseUrl.replace(/\/+$/, "");
		this.tenantId = options.tenantId;
		this.invokeKey = options.invokeKey;
	}

	async register(workerId: string): Promise<string> {
		const response = await this.send("POST", "/workers/register", {
			worker_id: workerId,
			cost_class: "local",
			capabilities: ["cpu"],
		});
		const payload = (await this.expectOk(response)) as { token: string };
		this.token = payload.token;
		return payload.token;
	}

	async claim(turnId: string, workerId: string): Promise<ClaimResult> {
		const response = await this.send("POST", `/turns/${turnId}/claim`, { worker_id: workerId });
		if (response.status === 409) return { acquired: false };
		const payload = (await this.expectOk(response)) as { acquired: boolean; fence_token: number };
		return { acquired: payload.acquired, fenceToken: payload.fence_token };
	}

	async renew(turnId: string, workerId: string, fenceToken: number, jobId: string): Promise<void> {
		const response = await this.send("POST", `/turns/${turnId}/renew`, {
			worker_id: workerId,
			fence_token: fenceToken,
			job_id: jobId,
		});
		await this.expectOk(response);
	}

	async context(turnId: string): Promise<TurnContext> {
		const response = await this.send("GET", `/turns/${turnId}/context`);
		return (await this.expectOk(response)) as TurnContext;
	}

	async postChunk(turnId: string, token: string, complete: boolean, fenceToken: number): Promise<void> {
		const response = await this.send("POST", `/turns/${turnId}/chunks`, {
			token,
			complete,
			fence_token: fenceToken,
		});
		await this.expectOk(response);
	}

	async postFailed(turnId: string, reason: string, fenceToken: number): Promise<void> {
		const response = await this.send("POST", `/turns/${turnId}/failed`, {
			reason,
			fence_token: fenceToken,
		});
		await this.expectOk(response);
	}

	async postSpend(
		turnId: string,
		fenceToken: number,
		vendor: string,
		model: string,
		inputTokens: number,
		outputTokens: number,
	): Promise<void> {
		const response = await this.send("POST", `/turns/${turnId}/spend`, {
			fence_token: fenceToken,
			vendor,
			model,
			input_tokens: inputTokens,
			output_tokens: outputTokens,
		});
		await this.expectOk(response);
	}

	private async send(method: "GET" | "POST", path: string, body?: unknown): Promise<Response> {
		const headers: Record<string, string> = {};
		if (this.invokeKey !== undefined) headers["X-Chatticus-Invoke-Key"] = this.invokeKey;
		if (this.token !== undefined) headers.Authorization = `Bearer ${this.token}`;
		if (body !== undefined) headers["Content-Type"] = "application/json";
		return fetch(`${this.baseUrl}/orgs/${this.tenantId}${path}`, {
			method,
			headers,
			body: body === undefined ? undefined : JSON.stringify(body),
		});
	}

	private async expectOk(response: Response): Promise<unknown> {
		const text = await response.text();
		if (!response.ok) throw new FrontDoorError(response.status, text);
		return text === "" ? {} : JSON.parse(text);
	}
}
```

## Step 9. `conversation/src/pi-worker.ts`

```ts
import type { Context } from "@earendil-works/chord";
import type { Models } from "@earendil-works/pi-ai/models";
import type { Storage } from "@earendil-works/pi-durable";
import type { FrontDoorClient, TurnContext } from "./front-door-client.ts";
import { fenceFor, storageIdFor } from "./storage/storage-support.ts";
import { type ChannelLine, runTurn, type TurnModel } from "./turn-runner.ts";

export type PiWorkerJob = {
	job_id: string;
	tenant_id: string;
	turn_id: string;
	bot_id: string;
	required_capabilities: string[];
};

export type PiWorkerDeps = {
	frontDoor: FrontDoorClient;
	openStorage: (storageId: string, fence: number) => Promise<Storage>;
	models: Models;
	model: TurnModel;
	renewIntervalMs: number;
	context: Context;
	retryBaseDelayMs?: number;
};

export type PiWorkerOutcome = "answered" | "failed" | "skipped";

export function linesFromContext(turnContext: TurnContext): ChannelLine[] {
	return turnContext.messages.map((message) => ({
		seq: message.seq,
		authorKind: message.author_kind,
		authorId: message.author_id,
		authorLabel:
			message.author_kind === "human"
				? "Person"
				: message.author_id === turnContext.bot_id
					? turnContext.bot_name
					: "Teammate",
		body: message.body,
	}));
}

export function splitAnswer(text: string): { token: string; complete: boolean }[] {
	if (text.length <= 1) return [{ token: text, complete: true }];
	const middle = Math.ceil(text.length / 2);
	return [
		{ token: text.slice(0, middle), complete: false },
		{ token: text.slice(middle), complete: true },
	];
}

export async function runPiWorkerJob(job: PiWorkerJob, deps: PiWorkerDeps): Promise<PiWorkerOutcome> {
	const workerId = job.job_id;
	const { frontDoor } = deps;
	await frontDoor.register(workerId);
	const claim = await frontDoor.claim(job.turn_id, workerId);
	if (!claim.acquired || !("fenceToken" in claim)) return "skipped";
	const fenceToken = claim.fenceToken;

	const turnContext = await frontDoor.context(job.turn_id);
	const storage = await deps.openStorage(
		storageIdFor(job.tenant_id, job.bot_id, turnContext.channel_id),
		fenceFor(turnContext.prompt_message_seq, fenceToken),
	);
	const renewTimer = setInterval(() => {
		frontDoor.renew(job.turn_id, workerId, fenceToken, job.job_id).catch(() => undefined);
	}, deps.renewIntervalMs);
	try {
		const outcome = await runTurn(
			storage,
			deps.models,
			deps.model,
			{
				turnId: job.turn_id,
				botId: turnContext.bot_id,
				botName: turnContext.bot_name,
				memory: turnContext.memory,
				lines: linesFromContext(turnContext),
				promptMessageSeq: turnContext.prompt_message_seq,
			},
			deps.context,
			deps.retryBaseDelayMs === undefined ? undefined : { retryBaseDelayMs: deps.retryBaseDelayMs },
		);
		if (outcome.kind === "failed") {
			await frontDoor.postFailed(job.turn_id, outcome.reason, fenceToken);
			return "failed";
		}
		await frontDoor.postSpend(
			job.turn_id,
			fenceToken,
			"openai",
			deps.model.modelId,
			outcome.usage.input,
			outcome.usage.output,
		);
		for (const chunk of splitAnswer(outcome.text)) {
			await frontDoor.postChunk(job.turn_id, chunk.token, chunk.complete, fenceToken);
		}
		return "answered";
	} finally {
		clearInterval(renewTimer);
	}
}
```

## Step 10. `conversation/test-support/pi-worker-harness.ts`

```ts
import { mkdirSync } from "node:fs";
import { join } from "node:path";
import { BACKGROUND_CONTEXT } from "@earendil-works/chord/context";
import { createModels } from "@earendil-works/pi-ai/models";
import { fauxAssistantMessage, fauxProvider } from "@earendil-works/pi-ai/providers/faux";
import type { Storage } from "@earendil-works/pi-durable";
import { MemoryStorage } from "@earendil-works/pi-durable/storage/memory";
import { openNodeJsonlStorage } from "@earendil-works/pi-durable/storage/jsonl/node";
import { FrontDoorClient } from "../src/front-door-client.ts";
import { type PiWorkerJob, runPiWorkerJob } from "../src/pi-worker.ts";

type ScriptStep = { text: string } | { error: string };

type HarnessInput = {
	baseUrl: string;
	tenantId: string;
	job: PiWorkerJob;
	script: ScriptStep[];
	storageDir?: string;
	invokeKey?: string;
};

const input = JSON.parse(process.argv[2] ?? "{}") as HarnessInput;

const faux = fauxProvider({ models: [{ id: "faux-reasoner", reasoning: true }] });
const models = createModels();
models.setProvider(faux.provider);

let lastRequestText = "";
faux.setResponses(
	input.script.map((step) => (context) => {
		lastRequestText = JSON.stringify(context);
		if ("error" in step) return fauxAssistantMessage("", { stopReason: "error", errorMessage: step.error });
		return fauxAssistantMessage(step.text);
	}),
);

async function openStorage(storageId: string): Promise<Storage> {
	if (input.storageDir === undefined) return new MemoryStorage();
	const directory = join(input.storageDir, storageId.replace(/[^A-Za-z0-9_-]/g, "_"));
	mkdirSync(directory, { recursive: true });
	return openNodeJsonlStorage(directory, BACKGROUND_CONTEXT);
}

const outcome = await runPiWorkerJob(input.job, {
	frontDoor: new FrontDoorClient({
		baseUrl: input.baseUrl,
		tenantId: input.tenantId,
		invokeKey: input.invokeKey,
	}),
	openStorage,
	models,
	model: { provider: faux.provider.id, modelId: "faux-reasoner", thinkingLevel: "low" },
	renewIntervalMs: 1000,
	context: BACKGROUND_CONTEXT,
	retryBaseDelayMs: 1,
});

console.log(JSON.stringify({ outcome, modelCalls: faux.state.callCount, lastRequestText }));
```

## Step 11. `conversation/test/turn-runner.test.ts` (pure helpers only)

```ts
import { describe, expect, test } from "vitest";
import {
	buildSystemPrompt,
	type ChannelLine,
	classifyError,
	formatLines,
	selectLinesToSync,
	type TurnInput,
} from "../src/turn-runner.ts";

const line = (seq: number, body: string, authorKind: "human" | "bot" = "human", authorId = "human-1"): ChannelLine => ({
	seq,
	authorKind,
	authorId,
	authorLabel: authorKind === "human" ? "Ryan" : "Ada",
	body,
});

const input = (lines: ChannelLine[], promptMessageSeq: number): TurnInput => ({
	turnId: "t1",
	botId: "bot-ada",
	botName: "Ada",
	memory: {},
	lines,
	promptMessageSeq,
});

describe("buildSystemPrompt", () => {
	test("renders the fixed line then memory lines sorted by key", () => {
		expect(buildSystemPrompt({ botName: "Ada", memory: { zebra: "z", apple: "a" } })).toBe(
			"You are Ada, a teammate in a Chatticus conversation. Answer briefly.
memory apple: a
memory zebra: z",
		);
	});

	test("renders only the fixed line when memory is empty", () => {
		expect(buildSystemPrompt({ botName: "Grace", memory: {} })).toBe(
			"You are Grace, a teammate in a Chatticus conversation. Answer briefly.",
		);
	});
});

describe("selectLinesToSync", () => {
	const lines = [
		line(1, "first"),
		line(2, "own", "bot", "bot-ada"),
		line(3, "grace", "bot", "bot-grace"),
		line(4, "second"),
		line(5, "after prompt"),
	];

	test("the first sync (lastSyncedSeq 0) includes this bot's own lines", () => {
		expect(selectLinesToSync(input(lines, 4), 0).map((l) => l.seq)).toEqual([1, 2, 3, 4]);
	});

	test("a later sync excludes this bot's own lines but keeps other bots' lines", () => {
		expect(selectLinesToSync(input(lines, 4), 1).map((l) => l.seq)).toEqual([3, 4]);
	});

	test("only lines above lastSyncedSeq and up to promptMessageSeq are selected", () => {
		expect(selectLinesToSync(input(lines, 4), 3).map((l) => l.seq)).toEqual([4]);
		expect(selectLinesToSync(input(lines, 4), 4)).toEqual([]);
	});
});

describe("formatLines", () => {
