describe("classifyError", () => {
	test("insufficient_quota", () => {
		expect(classifyError("429 insufficient_quota: exceeded")).toEqual({
			reason: "The model provider refused the request: the account is out of credits or over its quota.",
		});
	});

	test("401 and invalid_api_key", () => {
		const expected = { reason: "The model provider rejected the API key." };
		expect(classifyError("401 Unauthorized")).toEqual(expected);
		expect(classifyError("Incorrect API key: invalid_api_key")).toEqual(expected);
	});

	test("model_access_denied", () => {
		expect(classifyError("403 model_access_denied: no access")).toEqual({
			reason: "The model provider denied access to the configured model.",
		});
	});

	test("unsupported_value and invalid_request_error", () => {
		const expected = { reason: "The model provider rejected the request as invalid." };
		expect(classifyError("400 unsupported_value: bad")).toEqual(expected);
		expect(classifyError("400 invalid_request_error")).toEqual(expected);
